import { LazyCredential, type Credential } from './credentials'
import type { RelationshipHierarchy } from './orchestrator/dependencies/relationship-resolver'

export type UnloadedRecord = {
    content: string
    sysId: string
    table: string
    tableName: string
    name: string
}

export interface IConnector {
    setCurrentApplication(scopeId: string): Promise<void>
    getHost(): URL
    download(
        scope: string,
        options?: { method: 'complete' } | { method: 'incremental'; lastPull?: string }
    ): Promise<Response>
    moveToApp(sysIds: string[], scope: string): Promise<CustomizeOrMoveResult[]>
    uploadScopedAppPackage(
        file: Blob,
        options: {
            timeoutMs?: number | undefined
            loadDemoData?: boolean
            isStoreApp?: boolean
            registerScope?: boolean
            installAsync?: boolean
            appInfo?: {
                scope: string
                scopeId: string
                version: string
            }
        }
    ): Promise<{ trackerId: string; rollbackId: string } | undefined>
    getUpdateXMLCount(updateSetId: string): Promise<number>
    uninstallApplication(scopeId: string, isStoreApp: boolean): Promise<Response>
    appUpgradeStatus(scope: string): Promise<{
        finished: boolean
        id: string
    }>
    getProgress(progressId: string): Promise<{ status: string; percent_complete: number; status_message: string }>
    getUpdateMutex(): Promise<boolean>
    getInstanceBuildName(): Promise<string | undefined>
    appCreatorVendorPrefix(): Promise<string>
    getScopeInfo(
        scope?: string,
        scopeId?: string
    ): Promise<
        | undefined
        | {
              appId: string
              sysClassName: string
              active: boolean
              scope: string
              name: string
              shortDescription: string
          }
    >
    downloadUpdateSet(updateSetId: string, scopeId: string): Promise<Response>
    syntaxEditorCacheScriptIncludes(): Promise<Record<string, string>>
    syntaxEditorCompletionDefinitions(): Promise<string>
    syntaxEditorDefinitionsScriptIncludes(scriptIncludeIds: string[]): Promise<Record<string, string>>
    processorRequest(api: string, search: URLSearchParams): Promise<{ status: number; value: string }>
    unloadDependentRecords<T extends string>(
        table: T,
        sysId: string,
        relationship: RelationshipHierarchy<T>[]
    ): Promise<UnloadedRecord[]>
    unloadRecords(sysIds: string[], scopeId: string): Promise<UnloadedRecord[]>
    uploadXmlFiles(
        scope: string,
        files: { blob: Blob; name: string }[],
        options?: { timeoutMs?: number; targetUpdateSetId?: string }
    ): Promise<string>
}

/**
 * This class handles http communication with the ServiceNow instance
 */
export class Connector implements IConnector {
    private readonly credential: LazyCredential
    constructor(
        /**
         * The credential for authentication with the instance
         */
        credential: LazyCredential | Credential
    ) {
        if (credential instanceof LazyCredential) {
            this.credential = credential
        } else {
            this.credential = new LazyCredential(credential.instanceUrl, () => credential)
        }
    }

    public async uploadXmlFiles(
        scopeId: string,
        files: { blob: Blob; name: string }[],
        options: {
            timeoutMs?: number
            targetUpdateSetId?: string
        } = {}
    ): Promise<string> {
        const formData = new FormData()
        files.forEach((file) => {
            formData.append('files', file.blob, file.name)
        })

        const timeoutSignal = AbortSignal.timeout(options.timeoutMs ?? 300000)
        let response: Response
        try {
            response = await this.fetch(
                `api/fluent/load/${scopeId}`,
                {
                    method: 'POST',
                    body: formData,
                    signal: timeoutSignal,
                },
                new URLSearchParams({
                    ...(options.targetUpdateSetId ? { targetUpdateSetId: options.targetUpdateSetId } : {}),
                })
            )
        } catch (e) {
            if (timeoutSignal.aborted && timeoutSignal.reason.name === 'TimeoutError') {
                throw new Error(`The upload request timed out waiting for a response.`)
            }
            throw e
        }

        const responseJson = await response.json()
        if (!response.ok) {
            throw new Error(`Failed to upload XML files: ${responseJson?.result?.error ?? response.statusText}`)
        }

        return responseJson.result.targetUpdateSetId
    }

    public getHost(): URL {
        return this.credential.getUrl()
    }

    public async unloadRecords(sysIds: string[], scopeId: string): Promise<UnloadedRecord[]> {
        const response = await this.fetch(`api/sn_glider/metadata/unload/${scopeId}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(sysIds),
        })
        if (!response.ok) {
            const { error } = await response.json()
            if (error && error.message) {
                throw new Error(`Failed to unload records: ${error.message}`)
            }
            throw new Error(`Failed to unload records`)
        }
        const responseBody = await response.json()
        return responseBody.result.xmlRecords
    }

    public async unloadDependentRecords<T extends string>(
        table: T,
        sysId: string,
        tableGraphs: RelationshipHierarchy<T>[]
    ): Promise<UnloadedRecord[]> {
        const payload = {
            table,
            sysId,
            tableGraphs,
        }

        const response = await this.fetch('api/sn_glider/fluent_support/table_relationship_exporter', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
        })

        if (!response.ok) {
            if (response.status === 400 || response.status === 500) {
                const { error } = await response.json()
                throw new Error(`Failed to unload records for table ${table}: ${error.message}`)
            }

            throw new Error(`Failed to unload records for table ${table}: ${response.statusText}`)
        }

        const responseBody = await response.json()

        return responseBody.result.xmlRecords
    }

    public async processorRequest(api: string, search: URLSearchParams): Promise<{ status: number; value: string }> {
        const response = await this.fetch(
            `${api}.do`,
            {
                method: 'GET',
            },
            search
        )

        if (!response.ok) {
            throw new Error(`Failed to fetch records from ${api}: ${response.statusText}`)
        }

        const value = await response.text()

        return {
            status: response.status,
            value,
        }
    }

    public async getScopeInfo(
        scope?: string,
        scopeId?: string
    ): Promise<
        | undefined
        | {
              appId: string
              sysClassName: string
              active: boolean
              scope: string
              name: string
              shortDescription: string
          }
    > {
        if (!scope && !scopeId) {
            throw new Error(`No scope or scopeId provided`)
        }

        const sysparm_query =
            scopeId && scope ? `scope=${scope}^sys_id=${scopeId}` : scope ? `scope=${scope}` : `sys_id=${scopeId}`

        const scopeInfoResult = await this.fetchApiNowTable<
            {
                sys_id: string
                sys_class_name: string
                active: string
                scope: string
                name: string
                short_description: string
            }[]
        >('sys_scope', {
            sysparm_query,
            sysparm_fields: 'sys_id,sys_class_name,active,scope,name,short_description',
            sysparm_limit: '2',
        })

        if (!scopeInfoResult || scopeInfoResult.length === 0) {
            return undefined
        }

        const scopeInfo = scopeInfoResult[0]
        if (!scopeInfo) {
            throw new Error(
                `Multiple scopes detected with the scope name ${scope}! Please resolve the multiple application installations and try again.`
            )
        }

        return {
            appId: scopeInfo.sys_id,
            sysClassName: scopeInfo.sys_class_name,
            active: Boolean(scopeInfo.active),
            scope: scopeInfo.scope,
            name: scopeInfo.name,
            shortDescription: scopeInfo.short_description,
        }
    }

    public async moveToApp(sysIds: string[], scope: string): Promise<CustomizeOrMoveResult[]> {
        const response = await this.fetch(`/api/sn_glider/metadata/customize-global/${scope}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json; charset=UTF-8' },
            body: JSON.stringify(sysIds),
        })
        if (!response.ok) {
            throw new Error(`Error Customizing file(s): ${response.statusText}`)
        }

        const body = await response.json()
        return body.result
    }

    public async uploadScopedAppPackage(
        file: Blob,
        options: {
            timeoutMs?: number | undefined
            loadDemoData?: boolean
            isStoreApp?: boolean
            registerScope?: boolean
            installAsync?: boolean
            appInfo?: {
                scope: string
                scopeId: string
                version: string
            }
        }
    ): Promise<{ trackerId: string; rollbackId: string } | undefined> {
        const form = new FormData()
        form.append('upload_type', 'file')
        form.append('load_demo', options.loadDemoData !== undefined ? options.loadDemoData.toString() : String(true))
        form.append('sysparm_ck', await this.sysParmCk())
        form.append('attachFile', file)

        const timeoutSignal = AbortSignal.timeout(options.timeoutMs ?? 300000)

        const params = new URLSearchParams()
        params.set('sysparm_track_fluent_install', 'true')
        params.set(
            'sysparm_async_fluent_install',
            options.installAsync !== undefined ? options.installAsync.toString() : String(false)
        )
        if (options.appInfo) {
            params.set('sysparm_fluent_scope_id', options.appInfo.scopeId)
            params.set('sysparm_fluent_scope_name', options.appInfo.scope)
            params.set('sysparm_fluent_app_version', options.appInfo.version)
        }

        if (!options.isStoreApp) {
            params.set('sysparm_request_type', 'custom_app')
        }

        if (options.registerScope) {
            params.set('sysparm_register_scope', 'true')
        }

        try {
            const response = await this.fetch(
                'sn_appclient_upload_processor.do',
                {
                    method: 'POST',
                    body: form,
                    signal: timeoutSignal,
                },
                params
            )
            const isJsonResponse = response.headers.get('Content-Type')?.startsWith('application/json')

            if (isJsonResponse && (response.ok || response.status === 400)) {
                const result = await response.json()
                if (result.executionTracker) {
                    return { trackerId: result.executionTracker, rollbackId: result.rollbackContext }
                }
            }

            if (!response.ok) {
                if (response.status === 401) {
                    throw new Error('Insufficient permissions to install the app. Ensure you have the required roles.')
                }
                // TODO: Re-enable error throwing for non-401 failures once backward compatibility is ensured
                //throw new Error(`Failed to install the app: ${response.statusText}`)
            }
        } catch (e) {
            if (timeoutSignal.aborted && timeoutSignal.reason.name === 'TimeoutError') {
                throw new Error(`The deployment request timed out waiting for a response.`)
            }
            throw e
        }

        return undefined
    }

    public async setCurrentApplication(scopeId: string): Promise<void> {
        const response = await this.appsAjaxProcessor({
            sysparm_function: 'changeApplication',
            sysparm_value: scopeId,
        })

        if (!response.ok) {
            throw new Error(`Failed to set current application: ${response.statusText}`)
        }
    }

    public async uninstallApplication(scopeId: string, isStoreApp: boolean): Promise<Response> {
        return this.appsAjaxProcessor({
            sysparm_function: isStoreApp ? 'uninstallApplication' : 'deleteApplication',
            sysparm_sys_id: scopeId,
            sysparm_fluent_app: 'true',
            sysparm_delete_all: 'true',
        })
    }

    public async appUpgradeStatus(scope: string): Promise<{
        finished: boolean
        id: string
    }> {
        const upgradeHistory = await this.fetchApiNowTable<
            {
                upgrade_finished: boolean
                sys_id: string
            }[]
        >('sys_upgrade_history', {
            sysparm_query: `to_version=${scope}^ORDERBYDESCupgrade_started`,
            sysparm_fields: 'upgrade_finished,sys_id',
            sysparm_limit: '1',
        })

        return {
            finished: !!upgradeHistory?.[0]?.upgrade_finished,
            id: upgradeHistory?.[0]?.sys_id ?? '',
        }
    }

    public async getProgress(
        progressId: string
    ): Promise<{ status: string; percent_complete: number; status_message: string }> {
        const response = await this.fetch(`/api/sn_cicd/progress/${progressId}`, {
            method: 'GET',
            headers: { 'Content-Type': 'application/json' },
        })
        if (!response.ok) {
            throw new Error(`Failed to fetch progress status: ${response.statusText}`)
        }
        const body = (await response.json()) as {
            result: { status: string; percent_complete: number; status_message: string }
        }
        return body.result
    }

    public async getUpdateMutex(): Promise<boolean> {
        const r = await this.fetchApiNowTable<{ sys_id: string }[]>('sys_mutex', {
            sysparm_fields: 'sys_id',
            sysparm_query: 'name=Update-Mutex^acquiredISNOTEMPTY',
        })

        if (!r || (r && r.length < 1)) {
            return true
        }
        return false
    }

    public download(
        scope: string,
        options?: { method: 'complete' } | { method: 'incremental'; lastPull?: string }
    ): Promise<Response> {
        const params = new URLSearchParams()
        if (options?.method === 'incremental') {
            params.set('sysparam_mode', 'incremental')
            if (options.lastPull) {
                params.set('sysparam_timestamp', options.lastPull)
            }
        } else {
            params.set('sysparam_mode', 'complete')
        }

        return this.fetch(`/api/fluent/download/${scope}`, { method: 'GET' }, params)
    }

    public async downloadUpdateSet(updateSetId: string, scopeId: string): Promise<Response> {
        return this.fetch(
            '/fluent_update_set_export.do',
            { method: 'GET' },
            new URLSearchParams({
                sysparm_ck: await this.sysParmCk(),
                sysparm_sys_id: updateSetId,
                sysparm_app_sys_id: scopeId,
            })
        )
    }

    public async getInstanceBuildName(): Promise<string | undefined> {
        const response = await this.fetchApiNowTable<{ build_name: string }[]>('sys_cluster_state', {
            sysparm_fields: 'build_name',
        })

        return response ? response[0]?.build_name : undefined
    }

    public async appCreatorVendorPrefix(): Promise<string> {
        const response = await this.fetch('/api/now/appcreator/app/vendorprefix')

        const { result } = await response.json()
        return result
    }

    /**Produces the typescript definition for glide server scriptables */
    public async syntaxEditorCompletionDefinitions(): Promise<string> {
        const result = await this.fetch('/api/now/syntax_editor/completions?scope=')

        const serverRespose = (await result.json()) as { result: { result: string } }
        return serverRespose.result.result
    }

    /**
     * Mapping between script include identifiers and their sys_id
     * @returns Mapping of script to scripd sys_id (Example: { 'global.JSUtil': '1e2e4e24c1af42bea7f0c0f9fa40fbeb' })
     */
    public async syntaxEditorCacheScriptIncludes(): Promise<Record<string, string>> {
        const scriptsMap = await this.fetch('/api/now/syntax_editor/cache/sys_script_include', {
            headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        })

        if (!scriptsMap.ok) {
            throw new Error(`Failed to fetch script includes: ${scriptsMap.statusText}`)
        }

        const bodyJson = await scriptsMap.json()
        return JSON.parse(bodyJson.result.result).sys_script_include
    }

    /**Produces the definitions for script includes */
    public async syntaxEditorDefinitionsScriptIncludes(scriptIncludeIds: string[]): Promise<Record<string, string>> {
        const scriptsContent = await this.fetch('/api/now/syntax_editor/intellisense/sys_script_include', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
            body: JSON.stringify({ scriptIncludes: scriptIncludeIds }),
        })

        if (!scriptsContent.ok) {
            throw new Error(`Failed to fetch script include definitions: ${scriptsContent.statusText}`)
        }

        const {
            result: { result: scripts },
        } = (await scriptsContent.json()) as { result: { result: Record<string, string> } }

        return scripts
    }

    private async appsAjaxProcessor(params: Record<`sysparm_${string}`, string>): Promise<Response> {
        const form = new URLSearchParams({
            sysparm_processor: 'com.snc.apps.AppsAjaxProcessor',
            ...params,
            sysparm_ck: await this.sysParmCk(),
        })

        return this.fetch('/xmlhttp.do', {
            method: 'POST',
            body: form.toString(),
            headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8', Accept: '*/*' },
        })
    }

    /**
     * Fetch a resource from the ServiceNow instance
     * @param path Subpath to fetch from the instance (ex: /api/now/table/incident)
     * @param init Request options to pass to fetch (Default: { method: 'GET', headers: { 'Content-Type': 'application/json' } })
     * @returns The response from the fetch request or an error if the request failed
     */
    private async fetch(path: string, init?: RequestInit, params?: URLSearchParams): Promise<Response> {
        const initDefaults: RequestInit = {
            method: 'GET',
            ...init,
        }

        const authHeaders = await this.credential.getHeaders()
        const url = new URL(path, this.credential.getUrl())
        if (params) {
            url.search = params.toString()
        }

        const headers = { ...initDefaults.headers, ...authHeaders }

        return fetch(url, {
            ...initDefaults,
            headers,
        })
    }

    async getUpdateXMLCount(updateSetId: string): Promise<number> {
        const result = await this.fetchApiNowTable<
            {
                sys_id: string
            }[]
        >('sys_update_xml', {
            sysparm_query: `update_set=${updateSetId}`,
            sysparm_fields: `sys_id`,
        })

        if (!result) {
            return 0
        }

        return result.length
    }

    private async fetchApiNowTable<T extends object | object[]>(
        table: string,
        options: {
            sysparm_fields?: string
            sysparm_query?: string
            sysparm_limit?: `${number}`
            sysparm_offset?: `${number}`
            sysparm_display_value?: 'true' | 'false' | 'all'
            sysparm_no_count?: 'true' | 'false'
            sysparm_exclude_reference_link?: 'true' | 'false'
        }
    ): Promise<T | undefined> {
        const response = await this.fetch(
            `/api/now/table/${table}`,
            {
                method: 'GET',
                headers: { 'Content-Type': 'application/json' },
            },
            new URLSearchParams(options)
        )
        if (!response.ok) {
            throw new Error(response.statusText)
        }

        const body = (await response.json()) as { result: T }

        return body.result
    }
    private async sysParmCk(): Promise<string> {
        return this.credential.getSysParmCk()
    }
}

export type CustomizeOrMoveResult = {
    sysId: string
    table: string
}
